def download_worfbench_data(dataset: str, save_folder: str) -> None:
    """
    Download WorfBench dataset from Hugging Face.

    Args:
        dataset (str): Dataset name ("worfbench").
        save_folder (str): Directory to save data.
    """
    datasets_map = {'train': {'repo_id': 'zjunlp/WorFBench_train', 'filename': 'worfbench_train.json', 'split': 'train'}, 'test': {'repo_id': 'zjunlp/WorFBench_test', 'filename': 'worfbench_test.json', 'split': 'test'}}
    os.makedirs(save_folder, exist_ok=True)
    for split, info in datasets_map.items():
        repo_id = info['repo_id']
        filename = info['filename']
        dataset_split = info['split']
        save_path = os.path.join(save_folder, filename)
        if not os.path.exists(save_path):
            logger.info(f'Downloading {split} split of {dataset} from {repo_id}...')
            try:
                ds = load_dataset(repo_id, split=dataset_split)
                data = [item for item in ds]
                with open(save_path, 'w', encoding='utf-8') as f:
                    json.dump(data, f, ensure_ascii=False, indent=2)
                logger.info(f'Successfully downloaded and saved {filename} to {save_path}')
            except Exception as e:
                logger.error(f'Failed to download or save {filename}: {e}')
                raise
        else:
            logger.info(f'File {save_path} already exists, skipping download.')

class WorfBench(Benchmark):
    """
    WorfBench evaluation class for assessing LLM agents on complex workflow generation tasks.
    Assumed data structure:
    {
        "id": str,
        "task": str,
        "context": list of dicts (e.g., [{"title": str, "content": list of str}]),
        "expected_output": str or dict (sequence or graph),
        "type": str,
        "level": str
    }
    """

    def __init__(self, path: str=None, mode: str='test', **kwargs):
        path = os.path.expanduser(path or '~/.worfbench/data')
        super().__init__(name=type(self).__name__, path=path, mode=mode, **kwargs)

    def _load_data_from_file(self, file_name: str) -> Dict:
        if file_name is None:
            return None
        file_path = os.path.join(self.path, file_name)
        if not os.path.exists(file_path):
            download_worfbench_data(dataset='worfbench', save_folder=self.path)
        if not os.path.exists(file_path):
            logger.error(f'File {file_path} still does not exist after download attempt!')
            return None
        logger.info(f'Loading WorfBench data from {file_path} ...')
        data = load_json(path=file_path, type='json')
        if data is None:
            logger.error(f'Failed to load data from {file_path}')
            return None
        return data

    def _load_data(self) -> None:
        if self.mode in ['train', 'dev']:
            self._train_data = self._load_data_from_file(file_name=WORFBENCH_FILES_MAP['train'])
            if self.mode == 'dev':
                if self._train_data:
                    random.seed(42)
                    keys = list(self._train_data.keys())
                    n_dev = len(self._train_data[keys[0]]) // 10 or 1
                    indices = list(range(len(self._train_data[keys[0]])))
                    random.shuffle(indices)
                    self._train_data = {k: [v[i] for i in indices[:n_dev]] for k, v in self._train_data.items()}
        if self.mode == 'test':
            self._test_data = self._load_data_from_file(file_name=WORFBENCH_FILES_MAP['test'])

    def _get_label(self, example: Dict) -> Any:
        return example.get('expected_output', '')

    def _get_id(self, example: Dict) -> Any:
        return example.get('id', '')

    def evaluate(self, prediction: Any, label: Any) -> Dict:
        if isinstance(prediction, list) and isinstance(label, list):
            f1 = evaluate_workflow_sequence(prediction, label)
        elif isinstance(prediction, dict) and isinstance(label, dict):
            f1 = evaluate_workflow_graph(prediction, label)
        else:
            f1 = f1_score(prediction=str(prediction), ground_truth=str(label))
        em = exact_match_score(prediction=prediction, ground_truth=label)
        acc = acc_score(prediction=prediction, ground_truths=[label])
        return {'em': em, 'f1': f1, 'acc': acc}

    async def async_evaluate(self, graph: Callable, example: Dict) -> float:
        task = example.get('task', '')
        context = '\n'.join((f'{ctx.get('title', '')}: {' '.join(ctx.get('content', []))}' for ctx in example.get('context', []) if isinstance(ctx, dict)))
        inputs = f'Task: {task}\nContext: {context}\nGenerate workflow:\nAnswer:'
        try:
            generated_workflow = await graph(inputs)
        except Exception as e:
            logger.error(f'Error generating workflow: {e}')
            generated_workflow = ''
        label = self._get_label(example)
        metrics = self.evaluate(prediction=generated_workflow, label=label)
        return metrics['f1']

def _load_data_from_file(self, file_name: str) -> Dict:
    if file_name is None:
        return None
    file_path = os.path.join(self.path, file_name)
    if not os.path.exists(file_path):
        download_worfbench_data(dataset='worfbench', save_folder=self.path)
    if not os.path.exists(file_path):
        logger.error(f'File {file_path} still does not exist after download attempt!')
        return None
    logger.info(f'Loading WorfBench data from {file_path} ...')
    data = load_json(path=file_path, type='json')
    if data is None:
        logger.error(f'Failed to load data from {file_path}')
        return None
    return data

def download_raw_bigbenchhard_data(task_name: str, save_folder: str):
    """
    Download raw BIGBenchHard data for a specific task.
    
    Args:
        task_name: The name of the task to download
        save_folder: Directory to save the downloaded data file
        
    Raises:
        AssertionError: If task_name is not a valid BIGBenchHard task
    """
    assert task_name in ALL_TASKS, f"'{task_name}' is an invalid bigbenchhard task name. Available tasks: {list(ALL_TASKS.keys())}"
    file_name = ALL_TASKS[task_name]
    url = f'https://raw.githubusercontent.com/suzgunmirac/BIG-Bench-Hard/main/bbh/{file_name}'
    logger.info(f"Downloading BIGBenchHard '{task_name}' data from: {url}")
    download_file(url=url, save_file=os.path.join(save_folder, file_name))

class BIGBenchHard(Benchmark):
    """
    Benchmark class for BIGBenchHard dataset evaluation.
    
    BIGBenchHard is a subset of 23 challenging tasks from the BIG-bench evaluation suite.
    Each task example has the following structure:
    {
        "input": str,    # The input question/problem
        "target": str    # The expected answer/output
    }
    
    The benchmark supports automatic data splitting for training/validation purposes
    and evaluates predictions using exact match scoring.
    """

    def __init__(self, task: str, path: str=None, mode: str='all', dev_sample_num: int=0, seed: int=10, **kwargs):
        """
        Initialize BIGBenchHard benchmark.
        
        Args:
            task: The specific BIGBenchHard task name
            path: Path to store the dataset. Defaults to ~/.evoagentx/data/bigbenchhard/{task}
            mode: Data loading mode. Defaults to "all"
            dev_sample_num: Number of samples to use for dev set. If 0, all data goes to test set
            seed: Random seed for reproducibility. Defaults to 10
            **kwargs: Additional parameters for customization
            
        Raises:
            ValueError: If task is not a valid BIGBenchHard task name
        """
        if task not in ALL_TASKS:
            raise ValueError(f"Unknown task '{task}'. Available tasks: {list(ALL_TASKS.keys())}")
        self.task = task
        self.file_name = ALL_TASKS[task]
        self.dev_sample_num = dev_sample_num
        self.seed = seed
        path = os.path.expanduser(path or f'~/.evoagentx/data/bigbenchhard/{task}')
        super().__init__(name=f'BIGBenchHard-{self.task}', path=path, mode=mode, **kwargs)

    def _load_data_from_file(self, file_name: str) -> Optional[List[dict]]:
        """
        Load data from a specific file.
        
        Args:
            file_name: Name of the file to load
            
        Returns:
            List of loaded examples or None if file doesn't exist
        """
        if file_name is None:
            return None
        file_path = os.path.join(self.path, file_name)
        if not os.path.exists(file_path):
            download_raw_bigbenchhard_data(task_name=self.task, save_folder=self.path)
        logger.info(f'Loading BIGBenchHard data from {file_path}...')
        data = load_json(path=file_path, type='json')
        return data.get('examples', [])

    def _load_data(self):
        """
        Load and split data according to mode and dev_sample_num settings.
        
        Data splitting logic:
        - If dev_sample_num > 0: randomly samples examples for dev set, rest go to test set
        - If dev_sample_num = 0: all data goes to test set for evaluation
        - No training data provided (BIGBenchHard is designed for few-shot evaluation)
        """
        task_data = self._load_data_from_file(file_name=self.file_name)
        if task_data is None:
            logger.warning(f'No data loaded for task {self.task}')
            self._train_data = []
            self._dev_data = []
            self._test_data = []
            return
        self._train_data = []
        if self.dev_sample_num > 0 and len(task_data) > self.dev_sample_num:
            logger.info(f'Sampling {self.dev_sample_num} examples for dev set, rest for test set.')
            if self.seed is not None:
                set_seed(self.seed)
            dev_subset = random.sample(task_data, self.dev_sample_num)
            self._dev_data = dev_subset
            self._test_data = [item for item in task_data if item not in dev_subset]
        elif self.dev_sample_num > 0:
            logger.warning(f'dev_sample_num ({self.dev_sample_num}) >= total data size ({len(task_data)}). Using all data for dev set, none for test set.')
            self._dev_data = task_data
            self._test_data = []
        else:
            logger.info('dev_sample_num is 0, using all data for test set.')
            self._dev_data = []
            self._test_data = task_data

    def get_input_keys(self) -> List[str]:
        """
        Return the input keys expected by the benchmark.
        
        Returns:
            List containing "input" as the key for the problem text
        """
        return ['input']

    def _get_label(self, example: Any) -> Any:
        """
        Extract the ground truth label from an example.
        
        Args:
            example: The benchmark example
            
        Returns:
            The target answer/label
        """
        return example['target']

    def _get_id(self, example: Any) -> Any:
        """
        Extract the unique identifier from an example.
        
        BIGBenchHard examples don't have explicit IDs, so we use input text as identifier.
        
        Args:
            example: The benchmark example
            
        Returns:
            The input text as a unique identifier
        """
        return example.get('input', None)

    def evaluate(self, prediction: Any, label: Any) -> dict:
        """
        Score a prediction against the ground truth label.
        
        Uses exact match scoring with task-specific handling for certain tasks.
        
        Args:
            prediction: The predicted answer
            label: The ground truth answer
            
        Returns:
            Dictionary containing the exact match score
        """
        if self.task == 'dyck_languages':
            em = prediction.replace(' ', '') == label.replace(' ', '')
            return {'em': em}
        else:
            em = exact_match_score(prediction=prediction, ground_truth=label)
            return {'em': em}

def _load_data_from_file(self, file_name: str) -> Optional[List[dict]]:
    """
        Load data from a specific file.
        
        Args:
            file_name: Name of the file to load
            
        Returns:
            List of loaded examples or None if file doesn't exist
        """
    if file_name is None:
        return None
    file_path = os.path.join(self.path, file_name)
    if not os.path.exists(file_path):
        download_raw_bigbenchhard_data(task_name=self.task, save_folder=self.path)
    logger.info(f'Loading BIGBenchHard data from {file_path}...')
    data = load_json(path=file_path, type='json')
    return data.get('examples', [])

def download_real_mm_rag_data(save_dir: str='./data/real_mm_rag') -> str:
    """Download the REAL-MM-RAG FinReport dataset.
    
    Args:
        save_dir: Directory to save the dataset files
        
    Returns:
        str: Path to the saved dataset directory
    """
    try:
        os.makedirs(save_dir, exist_ok=True)
        dataset_path = os.path.join(save_dir, 'real_mm_rag_finreport.json')
        images_dir = os.path.join(save_dir, 'images')
        if os.path.exists(dataset_path) and os.path.exists(images_dir):
            image_files = [f for f in os.listdir(images_dir) if f.endswith(('.png', '.jpg', '.jpeg'))]
            if len(image_files) > 0:
                logger.info(f'Dataset already exists at {save_dir} with {len(image_files)} images')
                return save_dir
        logger.info('Downloading REAL-MM-RAG FinReport dataset...')
        dataset = load_dataset('ibm-research/REAL-MM-RAG_FinReport', split='test')
        images_dir = os.path.join(save_dir, 'images')
        os.makedirs(images_dir, exist_ok=True)
        metadata_list = []
        for i, example in enumerate(dataset):
            metadata = {'id': example['id'], 'query': example['query'], 'answer': example['answer'], 'image_filename': example['image_filename']}
            for level in ['rephrase_level_1', 'rephrase_level_2', 'rephrase_level_3']:
                if level in example and example[level]:
                    metadata[level] = example[level]
            metadata_list.append(metadata)
            if example['image'] is not None:
                image_filename = example['image_filename']
                image_path = os.path.join(images_dir, image_filename)
                example['image'].save(image_path)
                if i % 100 == 0:
                    logger.info(f'Saved {i + 1}/{len(dataset)} images...')
        dataset_path = os.path.join(save_dir, 'real_mm_rag_finreport.json')
        with open(dataset_path, 'w') as f:
            json.dump(metadata_list, f, indent=2)
        logger.info(f'Dataset downloaded to {save_dir}')
        logger.info(f'Total samples: {len(dataset)}')
        logger.info(f'Images saved to: {images_dir}')
        return save_dir
    except Exception as e:
        logger.error(f'Failed to download REAL-MM-RAG dataset: {str(e)}')
        raise

class RealMMRAG(Benchmark):
    """REAL-MM-RAG FinReport benchmark for multimodal retrieval evaluation.
    
    This benchmark contains financial report pages with associated queries,
    designed to test multimodal retrieval capabilities on real-world documents.
    """

    def __init__(self, path: str=None, mode: str='test', **kwargs):
        path = os.path.expanduser(path or '~/.evoagentx/data/real_mm_rag')
        self.dataset_file = Path(path) / 'real_mm_rag_finreport.json'
        self.images_dir = Path(path) / 'images'
        super().__init__(name=type(self).__name__, path=path, mode=mode, **kwargs)

    def _load_data(self):
        """Load the dataset from JSON file."""
        if not self.dataset_file.exists():
            download_real_mm_rag_data(save_dir=self.path)
        try:
            with open(self.dataset_file, 'r') as f:
                self._test_data = json.load(f)
            logger.info(f'Loaded {len(self._test_data)} samples from REAL-MM-RAG dataset')
        except Exception as e:
            logger.error(f'Failed to load dataset: {str(e)}')
            raise

    def _get_label(self, example: Any) -> Any:
        return example['answer']

    def _get_id(self, example: Any) -> Any:
        return example['id']

    def evaluate(self, prediction: Any, label: Any) -> dict:
        em = exact_match_score(prediction=prediction, ground_truth=label)
        f1 = f1_score(prediction=prediction, ground_truth=label)
        acc = acc_score(prediction=prediction, ground_truths=[label])
        return {'f1': f1, 'em': em, 'acc': acc}

    @property
    def data(self) -> List[Dict[str, Any]]:
        """Get the raw dataset."""
        return self._test_data

    def get_sample(self, index: int) -> Dict[str, Any]:
        """Get a single sample by index.
        
        Args:
            index: Sample index
            
        Returns:
            Dict containing query, image_filename, answer, and rephrases
        """
        if index >= len(self._test_data):
            raise IndexError(f'Index {index} out of range for dataset size {len(self._test_data)}')
        sample = self._test_data[index]
        sample['image_path'] = str(self.images_dir / sample['image_filename'])
        return sample

    def get_samples(self, start: int=0, end: Optional[int]=None) -> List[Dict[str, Any]]:
        """Get a range of samples.
        
        Args:
            start: Start index (inclusive)
            end: End index (exclusive). If None, goes to end of dataset
            
        Returns:
            List of samples
        """
        end = end or len(self._test_data)
        samples = []
        for i in range(start, min(end, len(self._test_data))):
            samples.append(self.get_sample(i))
        return samples

    def get_random_samples(self, n: int, seed: int=42) -> List[Dict[str, Any]]:
        """Get n random samples from the dataset.
        
        Args:
            n: Number of samples to return
            seed: Random seed for reproducibility
            
        Returns:
            List of random samples
        """
        import random
        random.seed(seed)
        indices = random.sample(range(len(self._test_data)), min(n, len(self._test_data)))
        return [self.get_sample(i) for i in indices]

    def get_query_variations(self, sample: Dict[str, Any]) -> List[str]:
        """Get all query variations for a sample.
        
        Args:
            sample: A sample from the dataset
            
        Returns:
            List of query variations (original + 3 rephrase levels)
        """
        queries = [sample['query']]
        for level in ['rephrase_level_1', 'rephrase_level_2', 'rephrase_level_3']:
            if level in sample and sample[level]:
                queries.append(sample[level])
        return queries

    def get_stats(self) -> Dict[str, Any]:
        """Get dataset statistics.
        
        Returns:
            Dictionary with dataset statistics
        """
        total_samples = len(self._test_data)
        has_rephrase_1 = sum((1 for s in self._test_data if s.get('rephrase_level_1')))
        has_rephrase_2 = sum((1 for s in self._test_data if s.get('rephrase_level_2')))
        has_rephrase_3 = sum((1 for s in self._test_data if s.get('rephrase_level_3')))
        unique_images = set((s['image_filename'] for s in self._test_data))
        return {'total_samples': total_samples, 'unique_images': len(unique_images), 'samples_with_rephrase_1': has_rephrase_1, 'samples_with_rephrase_2': has_rephrase_2, 'samples_with_rephrase_3': has_rephrase_3, 'avg_queries_per_image': total_samples / len(unique_images)}

def _load_data(self):
    """Load the dataset from JSON file."""
    if not self.dataset_file.exists():
        download_real_mm_rag_data(save_dir=self.path)
    try:
        with open(self.dataset_file, 'r') as f:
            self._test_data = json.load(f)
        logger.info(f'Loaded {len(self._test_data)} samples from REAL-MM-RAG dataset')
    except Exception as e:
        logger.error(f'Failed to load dataset: {str(e)}')
        raise

def download_raw_mbpp_data(name: str, save_folder: str):
    url = 'https://raw.githubusercontent.com/google-research/google-research/master/mbpp/sanitized-mbpp.json'
    logger.info(f'Downloading MBPP data from: {url}')
    download_file(url=url, save_file=os.path.join(save_folder, name))

class MBPP(CodingBenchmark):
    """Benchmark class for evaluating code generation on the MBPP dataset.
    
    MBPP (Mostly Basic Python Programming) is a collection of Python programming 
    problems designed to test a model's ability to generate functionally correct 
    code from natural language descriptions. This class handles loading the dataset, 
    evaluating solutions, and computing metrics such as pass@k.
    
    The original MBPP format is transformed to be compatible with the HumanEval
    benchmark format, allowing for consistent evaluation infrastructure.
    
    Each MBPP example has the following structure:
    {
        "task_id" (int): 2, 
        "prompt" (str): "Write a function to find the shared elements from the given two lists.",
        "code" (str): "def similar_elements(test_tup1, test_tup2):
  res = tuple(set(test_tup1) & set(test_tup2))
  return (res) ", 
        "test_imports": [] 
        "test_list" (List[str]): ['assert set(similar_elements((3, 4, 5, 6),(5, 7, 4, 10))) == set((4, 5))', 'assert set(similar_elements((1, 2, 3, 4),(5, 4, 3, 7))) == set((3, 4))', 'assert set(similar_elements((11, 12, 14, 13),(17, 15, 14, 13))) == set((13, 14))']
    }
    
    Attributes:
        k: An integer or list of integers specifying which pass@k metrics to compute
    """

    def __init__(self, path: str=None, mode: str='all', timeout: int=60, k: Union[int, list]=1, **kwargs):
        path = os.path.expanduser(path or '~/.evoagentx/data/mbpp')
        self.k = k
        super().__init__(name=type(self).__name__, path=path, mode=mode, timeout=timeout, **kwargs)

    def _load_data(self):
        data_path = os.path.join(self.path, 'sanitized-mbpp.json')
        if not os.path.exists(data_path):
            download_raw_mbpp_data(name='sanitized-mbpp.json', save_folder=self.path)
        if self.mode == 'train' or self.mode == 'all':
            self._train_data = None
        if self.mode == 'dev' or self.mode == 'all':
            self._dev_data = None
        if self.mode == 'test' or self.mode == 'all':
            self._test_data = load_mbpp_data(data_path)

    def _get_id(self, example: Any) -> Any:
        return example['task_id']

    def _get_label(self, example: Any) -> Any:
        return {'task_id': example['task_id'], 'canonical_solution': example['canonical_solution'], 'test': example['test'], 'entry_point': example['entry_point']}

    def evaluate(self, prediction: Any, label: Any) -> dict:
        """
        Evaluate the solution code.

        Args:
            prediction (str | List[str]): The solution code(s).
            label (dict | List[dict]): The unit test code(s).

        Returns:
            dict: The evaluation metrics (pass@k).
        """
        prediction, label = self._check_evaluation_inputs(prediction, label)
        results = []
        for solution in prediction:
            solution_states = []
            for label_data in label:
                task_id = label_data['task_id']
                prompt = self.get_example_by_id(task_id)['prompt']
                unit_test = label_data['test']
                entry_point = label_data['entry_point']
                state, message = self.check_solution(task_id=task_id, solution=prompt + '\n' + solution, test=unit_test, entry_point=entry_point)
                if state != self.SUCCESS:
                    break
                solution_states.append(state)
            results.append(len(solution_states) == len(label) and all((state == self.SUCCESS for state in solution_states)))
        k_list = [self.k] if isinstance(self.k, int) else self.k
        pass_at_k = self.compute_pass_at_k(results, k_list)
        return pass_at_k

def _load_data(self):
    data_path = os.path.join(self.path, 'sanitized-mbpp.json')
    if not os.path.exists(data_path):
        download_raw_mbpp_data(name='sanitized-mbpp.json', save_folder=self.path)
    if self.mode == 'train' or self.mode == 'all':
        self._train_data = None
    if self.mode == 'dev' or self.mode == 'all':
        self._dev_data = None
    if self.mode == 'test' or self.mode == 'all':
        self._test_data = load_mbpp_data(data_path)

class AFlowMBPP(MBPP):
    """
    AFlow-specific implementation of MBPP benchmark.
    """

    def __init__(self, path: str=None, mode: str='all', timeout: int=60, k: Union[int, list]=1, **kwargs):
        path = os.path.expanduser(path or '~/.evoagentx/data/aflow/mbpp')
        super().__init__(path=path, mode=mode, timeout=timeout, k=k, **kwargs)

    def _load_data_from_file(self, file_name: str):
        if file_name is None:
            return None
        file_path = os.path.join(self.path, file_name)
        if not os.path.exists(file_path):
            download_aflow_benchmark_data(dataset='mbpp', save_folder=self.path)
        return load_json(path=file_path, type='jsonl')

    def _load_data(self):
        if self.mode == 'train' or self.mode == 'all':
            logger.info(f'Loading train data from {AFLOW_DATASET_FILES_MAP['mbpp']['train']}')
            self._train_data = self._load_data_from_file(file_name=AFLOW_DATASET_FILES_MAP['mbpp']['train'])
        if self.mode == 'dev' or self.mode == 'all':
            logger.info(f'Loading dev data from {AFLOW_DATASET_FILES_MAP['mbpp']['dev']}')
            self._dev_data = self._load_data_from_file(file_name=AFLOW_DATASET_FILES_MAP['mbpp']['dev'])
        if self.mode == 'test' or self.mode == 'all':
            logger.info(f'Loading test data from {AFLOW_DATASET_FILES_MAP['mbpp']['test']}')
            self._test_data = self._load_data_from_file(file_name=AFLOW_DATASET_FILES_MAP['mbpp']['test'])
        self._test_cases = self._load_data_from_file(file_name=AFLOW_DATASET_FILES_MAP['mbpp']['test_cases'])

    def _get_label(self, example: Any):
        return {'task_id': example['task_id'], 'canonical_solution': example['code'], 'test': example['test'], 'entry_point': example['entry_point']}

    def extract_test_cases_with_entry_point(self, entry_point: str):
        hardcoded_cases = {'remove_odd': '', 'replace_spaces': '', 'snake_to_camel': '', 'Split': '', 'swap_List': '', 'square_Sum': '', 'sort_sublists': '', 'unique_sublists': ''}
        if entry_point in hardcoded_cases:
            return hardcoded_cases[entry_point]
        for case in self._test_cases:
            if case['entry_point'] == entry_point:
                return case['test']
        return None

    async def async_evaluate(self, graph: Callable, example: Any) -> float:
        prompt, entry_point = (example['prompt'], example['entry_point'])
        solution = await graph(prompt, entry_point)
        label = self._get_label(example)
        metrics = await super().async_evaluate(prediction=solution, label=label)
        return metrics['pass@1']

    def evaluate(self, prediction: Any, label: Any) -> dict:
        """
        Evaluate the solution code.

        Args:
            prediction (str | List[str]): The solution code(s).
            label (dict | List[dict]): The unit test code(s).

        Returns:
            dict: The evaluation metrics (pass@k).
        """
        prediction, label = self._check_evaluation_inputs(prediction, label)
        results = []
        for solution in prediction:
            solution_states = []
            for label_data in label:
                task_id = label_data['task_id']
                prompt = self.get_example_by_id(task_id)['prompt']
                unit_test = label_data['test']
                entry_point = label_data['entry_point']
                state, message = self.check_solution(task_id=task_id, solution=prompt + '\n' + solution, test=unit_test, entry_point=entry_point, use_entrypoint_as_input=False)
                if state != self.SUCCESS:
                    break
                solution_states.append(state)
            results.append(len(solution_states) == len(label) and all((state == self.SUCCESS for state in solution_states)))
        k_list = [self.k] if isinstance(self.k, int) else self.k
        pass_at_k = self.compute_pass_at_k(results, k_list)
        return pass_at_k

def _load_data_from_file(self, file_name: str):
    if file_name is None:
        return None
    file_path = os.path.join(self.path, file_name)
