    math_agent = ActionAgent(name='MathAgent', description='Performs mathematical operations', inputs=[{'name': 'a', 'type': 'int', 'description': 'First number', 'required': True}, {'name': 'b', 'type': 'int', 'description': 'Second number', 'required': True}], outputs=[{'name': 'result', 'type': 'int', 'description': 'Result', 'required': True}], execute_func=add_numbers)
    save_path = './examples/output/test_math_agent.json'
