def run_mcp_example():
    """
    Run a simple example using the MCP toolkit to search for research papers about 'artificial intelligence'.
    This uses the sample_mcp.config file to configure the arXiv MCP client.
    """
    print('\n===== MCP TOOLKIT EXAMPLE (arXiv) =====\n')
    config_path = os.path.join(os.getcwd(), 'examples', 'tools', 'sample_mcp.config')
    print(f'Loading MCP configuration from: {config_path}')
    try:
        mcp_toolkit = MCPToolkit(config_path=config_path)
        toolkits = mcp_toolkit.get_toolkits()
        print(f'✓ Connected to {len(toolkits)} MCP server(s)')
        arxiv_tool = None
        for toolkit_item in toolkits:
            for tool in toolkit_item.get_tools():
                print(f'Tool: {tool.name}')
                print(f'Description: {tool.description}')
                print('-' * 30)
                if 'search' in tool.name.lower() or 'arxiv' in tool.name.lower():
                    arxiv_tool = tool
                    break
            if arxiv_tool:
                break
        if arxiv_tool:
            print(f'✓ Found arXiv tool: {arxiv_tool.name}')
            print(f'  Description: {arxiv_tool.description}')
            search_query = 'artificial intelligence'
            print(f"\nSearching for research papers about: '{search_query}'")
            result = arxiv_tool(**{'query': search_query})
            print('\nSearch Results:')
            print('-' * 50)
            print(f'Result type: {type(result)}')
            print(f'Result content: {result}')
            print('-' * 50)
            print('✓ MCP arXiv example completed')
        else:
            print('❌ No suitable arXiv search tool found in the MCP configuration.')
    except Exception as e:
        print(f'❌ Error running MCP example: {str(e)}')
        print('Make sure the arXiv MCP server is properly configured and running.')
    finally:
        if 'mcp_toolkit' in locals():
            mcp_toolkit.disconnect()
            print('✓ MCP connection closed')

def run_script_execution(interpreter):
    """
    Run a script file using the execute_script method of the interpreter.
    
    Args:
        interpreter: An instance of a code interpreter
    """
    script_path = os.path.join(os.getcwd(), 'examples', 'tools', 'hello_world.py')
    if not os.path.exists(script_path):
        print(f'Error: Script file not found at {script_path}')
        return
    print(f'Executing script file: {script_path}')
    result = interpreter.execute_script(script_path, 'python')
    print('\nScript Execution Result:')
    print('-' * 50)
    print(result)
    print('-' * 50)

class CustomProgram:

    def __init__(self, model: OpenAILLM):
        self.model = model
        self.prompt = "Let's think step by step to answer the math question: {problem}"

    def save(self, path: str):
        params = {'prompt': self.prompt}
        with open(path, 'w') as f:
            json.dump(params, f)

    def load(self, path: str):
        with open(path, 'r') as f:
            params = json.load(f)
            self.prompt = params['prompt']

    def __call__(self, problem: str) -> Tuple[str, dict]:
        prompt = self.prompt.format(problem=problem)
        response = self.model.generate(prompt=prompt)
        solution = response.content
        return (solution, {'problem': problem, 'solution': solution})

def save(self, path: str):
    params = {'prompt': self.prompt}
    with open(path, 'w') as f:
        json.dump(params, f)

def load(self, path: str):
    with open(path, 'r') as f:
        params = json.load(f)
        self.prompt = params['prompt']

class SinglePromptProgram:
    """
    A program that uses a single, evolvable prompt to process tasks.
    
    This program uses few-shot learning combined with an evolvable chain-of-thought
    prefix to improve task performance through evolutionary optimization.
    """

    def __init__(self, model: OpenAILLM, task_name: str):
        """
        Initialize the single prompt program.
        
        Args:
            model: The language model to use for inference
            task_name: Name of the task for loading few-shot examples
        """
        self.model = model
        self.task_name = task_name
        lib_path = os.path.join(os.path.dirname(__file__), 'lib_prompt', f'{task_name}.txt')
        try:
            with open(lib_path, 'r', encoding='utf-8') as f:
                examples = [line.strip() for line in f if line.strip()]
        except FileNotFoundError:
            examples = []
        self.fewshot_prompt = '\n'.join(examples)
        self.chain_of_thought_prefix = ["Let's think step by step.", "Let's work this out in a step by step way to be sure we have the right answer.", 'First,', "Let's think about this logically.", "Let's solve this problem by splitting it into steps.", "Let's be realistic and think step by step.", "Let's think like a detective step by step.", "Let's think", 'Before we dive into the answer,', 'The answer is after the proof.', "Let's break this problem down step by step.", "We'll tackle this math task one piece at a time.", "Let's approach this logically, step by step.", "We'll solve this by analyzing each part of the problem.", "Let's unravel this mathematical challenge gradually.", "We'll methodically work through this problem together.", "Let's systematically dissect this math task.", "We'll take this mathematical reasoning challenge one step at a time.", "Let's meticulously examine each aspect of this problem.", "We'll thoughtfully progress through this task step by step."]
        self.task_prompt = "Please provide the answer in the format: 'the answer is ."

    def __call__(self, input: str) -> tuple[str, dict]:
        """
        Execute the program with the given input.
        
        Args:
            input: The input text to process
            
        Returns:
            Tuple of (answer, metadata)
        """
        prefix = self.chain_of_thought_prefix[0] if isinstance(self.chain_of_thought_prefix, list) else self.chain_of_thought_prefix
        prompt_body = []
        if self.fewshot_prompt:
            prompt_body.append(self.fewshot_prompt.replace('<prompt>', prefix))
        prompt_body.append(f'Q: {input}')
        prompt_body.append(f'A: {prefix}')
        full_prompt = f'\n'.join(prompt_body) + f'{self.task_prompt}'
        response = self.model.generate(prompt=full_prompt)
        text = response.content.strip()
        match = re.search('the answer is\\s*(.*)', text, re.IGNORECASE)
        answer = match.group(1).strip().rstrip('.') if match else 'N/A'
        return (answer, {'full_prompt': full_prompt})

    def save(self, path: str):
        """Save the program state (placeholder for future implementation)."""
        pass

    def load(self, path: str):
        """Load the program state (placeholder for future implementation)."""
        pass

def __init__(self, model: OpenAILLM, task_name: str):
    """
        Initialize the single prompt program.
        
        Args:
            model: The language model to use for inference
            task_name: Name of the task for loading few-shot examples
        """
    self.model = model
    self.task_name = task_name
    lib_path = os.path.join(os.path.dirname(__file__), 'lib_prompt', f'{task_name}.txt')
    try:
        with open(lib_path, 'r', encoding='utf-8') as f:
            examples = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        examples = []
    self.fewshot_prompt = '\n'.join(examples)
    self.chain_of_thought_prefix = ["Let's think step by step.", "Let's work this out in a step by step way to be sure we have the right answer.", 'First,', "Let's think about this logically.", "Let's solve this problem by splitting it into steps.", "Let's be realistic and think step by step.", "Let's think like a detective step by step.", "Let's think", 'Before we dive into the answer,', 'The answer is after the proof.', "Let's break this problem down step by step.", "We'll tackle this math task one piece at a time.", "Let's approach this logically, step by step.", "We'll solve this by analyzing each part of the problem.", "Let's unravel this mathematical challenge gradually.", "We'll methodically work through this problem together.", "Let's systematically dissect this math task.", "We'll take this mathematical reasoning challenge one step at a time.", "Let's meticulously examine each aspect of this problem.", "We'll thoughtfully progress through this task step by step."]
    self.task_prompt = "Please provide the answer in the format: 'the answer is ."

def run_evaluation(samples: List[Dict], top_k: int=5) -> Dict[str, float]:
    """Run evaluation on HotPotQA samples."""
    metrics = defaultdict(list)
    for sample in samples:
        question = sample['question']
        context = sample['context']
        supporting_facts = sample['supporting_facts']
        corpus_id = sample['_id']
        logger.info(f'Processing sample: {corpus_id}, question: {question}')
        corpus = create_corpus_from_context(context, corpus_id)
        logger.info(f'Created corpus with {len(corpus.chunks)} chunks')
        search_engine.add(index_type='graph', nodes=corpus, corpus_id=corpus_id)
        query = Query(query_str=question, top_k=top_k)
        result = search_engine.query(query, corpus_id=corpus_id)
        retrieved_chunks = result.corpus.chunks
        logger.info(f'Retrieved {len(retrieved_chunks)} chunks for query')
        logger.info(f'content:\n{retrieved_chunks}')
        sample_metrics = evaluate_retrieval(retrieved_chunks, supporting_facts, top_k)
        for metric_name, value in sample_metrics.items():
            metrics[metric_name].append(value)
        logger.info(f'Metrics for sample {corpus_id}: {sample_metrics}')
        CHECK_SAVE = False
        if CHECK_SAVE:
            search_engine.save(graph_exported=True)
            search_engine.clear(corpus_id=corpus_id)
            search_engine1 = RAGEngine(config=rag_config, storage_handler=storage_handler, llm=llm)
            search_engine1.load(index_type='graph')
            query = Query(query_str=question, top_k=top_k)
            result = search_engine1.query(query, corpus_id=corpus_id)
            retrieved_chunks = result.corpus.chunks
            logger.info(f'Retrieved {len(retrieved_chunks)} chunks for query')
            logger.info(f'content:\n{retrieved_chunks}')
            sample_metrics = evaluate_retrieval(retrieved_chunks, supporting_facts, top_k)
            logger.info(f'Metrics for sample {corpus_id}: {sample_metrics}')
    avg_metrics = {name: sum(values) / len(values) for name, values in metrics.items()}
    return avg_metrics

def save_intermediate_result(data, stage: str, output_dir: str):
    """Save intermediate results to JSON file"""
    os.makedirs(output_dir, exist_ok=True)
    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    filename = f'{stage}_{timestamp}.json'
    filepath = os.path.join(output_dir, filename)
    if hasattr(data, 'to_dict'):
        data_dict = data.to_dict()
    elif hasattr(data, '__dict__'):
        data_dict = data.__dict__.copy()
        for key, value in data_dict.items():
            if hasattr(value, '__dict__') and (not isinstance(value, (str, int, float, bool, list, dict, type(None)))):
                try:
                    json.dumps(value)
                except (TypeError, ValueError):
                    data_dict[key] = str(value)
    else:
        data_dict = data
    try:
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(data_dict, f, ensure_ascii=False, indent=2, default=str)
        print(f'Saved {stage} results to: {filepath}')
    except (TypeError, ValueError) as e:
        print(f'Warning: Cannot fully serialize {stage} results ({e}), saving string representation')
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(str(data))
    return filepath

def verify_and_extract_code(llm: LiteLLM, goal: str, output: str, target_dir: str):
    """4. Verify code and extract to files"""
    wait_for_user_confirmation('code verification and extraction')
    print('Starting code verification and extraction...')
    verifier = CodeVerification()
    verified = verifier.execute(llm=llm, inputs={'requirements': goal, 'code': output}).verified_code
    os.makedirs(target_dir, exist_ok=True)
    blocks = extract_code_blocks(verified)
    if len(blocks) == 1:
        path = os.path.join(target_dir, 'index.html')
        with open(path, 'w') as f:
            f.write(blocks[0])
        print(f'HTML file generated: {path}')
        return
    extractor = CodeExtraction()
    res = extractor.execute(llm=llm, inputs={'code_string': verified, 'target_directory': target_dir})
    print(f'Extracted {len(res.extracted_files)} files:')
    for name, p in res.extracted_files.items():
        print(f' - {name}: {p}')
    if res.main_file:
        ext = os.path.splitext(res.main_file)[1].lower()
        tip = 'can be opened in browser' if ext == '.html' else 'main entry file'
        print(f'\nMain file: {res.main_file}, {tip}')

class MessageBenchmark(Benchmark):
    """
    Adapt dataset in messages format, automatically extract last user/assistant round.
    """

    def __init__(self, path: str, mode: str='train'):
        super().__init__(name='MessageBenchmark', path=path, mode=mode)

    def _load_data(self):
        import json
        file_path = os.path.join(self.path, 'worfbench_train.json')
        with open(file_path, 'r', encoding='utf-8') as f:
            self._train_data = json.load(f)

    def _get_label(self, example):
        return [m['content'] for m in example['messages'] if m['role'] == 'assistant'][-1]

    def _get_id(self, example):
        user_msg = [m['content'] for m in example['messages'] if m['role'] == 'user'][-1]
        return example.get('source', '') + '_' + user_msg[:20]

    def evaluate(self, prediction, label):
        from evoagentx.benchmark.measures import exact_match_score, f1_score, acc_score
        em = exact_match_score(prediction, label)
        f1 = f1_score(prediction, label)
        acc = acc_score(prediction, [label])
        return {'em': em, 'f1': f1, 'acc': acc}

def _load_data(self):
    import json
    file_path = os.path.join(self.path, 'worfbench_train.json')
    with open(file_path, 'r', encoding='utf-8') as f:
        self._train_data = json.load(f)

class TestModule(unittest.TestCase):

    def setUp(self):
        self.save_file = 'tests/agents/saved_agent.json'

    def test_initialization(self):
        agent_data = {'name': 'test_agent', 'description': 'test_agent_description', 'llm_config': {'class_name': 'LiteLLMConfig', 'model': 'gpt-4o-mini', 'openai_key': 'xxxxx'}, 'actions': [{'class_name': 'Action', 'name': 'test_action_name', 'description': 'test_action_desc', 'prompt': 'test_action_prompt'}]}
        agent = Agent.from_dict(agent_data)
        self.assertEqual(agent.llm_config.model, 'gpt-4o-mini')
        self.assertTrue(isinstance(agent.llm, LiteLLM))
        self.assertTrue(isinstance(agent.actions[0], Action))
        self.assertTrue(len(agent.get_all_actions()) == 1)
        action = agent.get_action('test_action_name')
        self.assertEqual(action.name, 'test_action_name')
        self.assertEqual(action.description, 'test_action_desc')
        prompts = agent.get_prompts()
        self.assertEqual(len(prompts), 1)
        self.assertEqual(prompts['test_action_name']['system_prompt'], None)
        self.assertEqual(prompts['test_action_name']['prompt'], 'test_action_prompt')
        agent.set_prompt('test_action_name', 'new_test_action_prompt', 'new_system_prompt')
        self.assertTrue(agent.system_prompt, 'new_system_prompt')
        self.assertEqual(agent.get_action('test_action_name').prompt, 'new_test_action_prompt')
        agent.set_prompts({'test_action_name': {'system_prompt': 'new_system_prompt_v2', 'prompt': 'new_test_action_prompt_v2'}})
        self.assertTrue(agent.system_prompt, 'new_system_prompt_v2')
        self.assertEqual(agent.get_action('test_action_name').prompt, 'new_test_action_prompt_v2')
        agent2 = Agent.from_dict(agent_data)
        agent_list = [agent]
        self.assertTrue(agent2 not in agent_list)
        self.assertTrue(agent2 != agent)
        agent2_id = agent2.agent_id
        agent2.agent_id = agent.agent_id
        self.assertTrue(agent2 in agent_list)
        self.assertTrue(agent2 == agent)
        agent2.agent_id = agent2_id

    def test_save_agent(self):
        llm_config = LiteLLMConfig(model='gpt-4o-mini', openai_key='xxxxx')
        agent = Agent(name='Bob', description='Bob is an engineer. He excels in writing and reviewing codes for different projects.', system_prompt='You are an excellent engineer and you can solve diverse coding tasks.', llm_config=llm_config, actions=[{'name': 'WriteFileToDisk', 'description': 'save several files to local storage.', 'tools': [{'name': 'FileToolKit', 'tools': [{'name': 'WriteFile', 'description': 'Write file to disk', 'inputs': {}}]}]}])
        agent.save_module(path=self.save_file)
        loaded_agent = Agent.from_file(path=self.save_file, llm_config=llm_config)
        self.assertEqual(agent, loaded_agent)

    def tearDown(self):
        if os.path.exists(self.save_file):
            os.remove(self.save_file)

def tearDown(self):
    if os.path.exists(self.save_file):
        os.remove(self.save_file)

